import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { vendorAPI, apiCall } from '../../services/apiService';
import './VendorDashboard.css';

const VendorDashboard = () => {
  const { user } = useAuth();
  const [dashboardData, setDashboardData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    setIsLoading(true);
    setError('');

    const result = await apiCall(vendorAPI.getDashboard);

    if (result.success) {
      setDashboardData(result.data);
    } else {
      setError(result.error);
    }

    setIsLoading(false);
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading dashboard...
      </div>
    );
  }

  if (error) {
    return (
      <div className="container">
        <div className="alert alert-error">
          {error}
        </div>
      </div>
    );
  }

  const { profile, applications = [], applicationCount = 0 } = dashboardData || {};
  const hasProfile = profile && profile.profileComplete;

  return (
    <div className="vendor-dashboard">
      <div className="page-header">
        <div className="container">
          <h1>Vendor Dashboard</h1>
          <p>Welcome back, {user?.username}!</p>
        </div>
      </div>

      <div className="container">
        {/* Quick Stats */}
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-icon">👤</div>
            <div className="stat-content">
              <div className="stat-label">Profile Status</div>
              <div className="stat-value">
                {hasProfile ? 'Complete' : 'Incomplete'}
              </div>
            </div>
            <div className={`stat-indicator ${hasProfile ? 'success' : 'warning'}`}>
              {hasProfile ? '✓' : '!'}
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">📄</div>
            <div className="stat-content">
              <div className="stat-label">Applications</div>
              <div className="stat-value">{applicationCount}</div>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">📍</div>
            <div className="stat-content">
              <div className="stat-label">Operating Region</div>
              <div className="stat-value">
                {profile?.operatingRegion || 'Not Set'}
              </div>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">🍽️</div>
            <div className="stat-content">
              <div className="stat-label">Cuisine Type</div>
              <div className="stat-value">
                {profile?.cuisineSpecialties?.split(',')[0]?.trim() || 'Not Set'}
              </div>
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="dashboard-content">
          {/* Profile Section */}
          <div className="dashboard-section">
            <div className="section-header">
              <h2>Your Profile</h2>
              <Link to="/vendor/profile" className="btn btn-outline">
                {hasProfile ? 'Edit Profile' : 'Complete Profile'}
              </Link>
            </div>

            {hasProfile ? (
              <div className="profile-summary">
                <div className="profile-item">
                  <strong>Business Name:</strong> {profile.name}
                </div>
                <div className="profile-item">
                  <strong>Cuisine Specialties:</strong> {profile.cuisineSpecialties}
                </div>
                <div className="profile-item">
                  <strong>Operating Region:</strong> {profile.operatingRegion}
                </div>
                {profile.phoneNumber && (
                  <div className="profile-item">
                    <strong>Phone:</strong> {profile.phoneNumber}
                  </div>
                )}
                {profile.businessAddress && (
                  <div className="profile-item">
                    <strong>Address:</strong> {profile.businessAddress}
                  </div>
                )}
              </div>
            ) : (
              <div className="incomplete-profile">
                <div className="incomplete-icon">⚠️</div>
                <h3>Profile Incomplete</h3>
                <p>Complete your vendor profile to start applying for licenses.</p>
                <Link to="/vendor/profile" className="btn btn-primary">
                  Complete Profile Now
                </Link>
              </div>
            )}
          </div>

          {/* Applications Section */}
          <div className="dashboard-section">
            <div className="section-header">
              <h2>Your Applications</h2>
              <Link to="/vendor/applications" className="btn btn-outline">
                View All Applications
              </Link>
            </div>

            {applications.length === 0 ? (
              <div className="no-applications">
                {hasProfile ? (
                  <>
                    <div className="no-app-icon">📄</div>
                    <h3>No Applications Yet</h3>
                    <p>Ready to apply for your food truck license?</p>
                    <Link to="/vendor/applications" className="btn btn-primary">
                      Create Application
                    </Link>
                  </>
                ) : (
                  <>
                    <div className="no-app-icon">🔒</div>
                    <h3>Complete Your Profile First</h3>
                    <p>You need to complete your profile before applying for licenses.</p>
                    <Link to="/vendor/profile" className="btn btn-primary">
                      Complete Profile
                    </Link>
                  </>
                )}
              </div>
            ) : (
              <div className="recent-applications">
                <h4>Recent Applications</h4>
                {applications.slice(0, 3).map(application => (
                  <ApplicationCard key={application.id} application={application} />
                ))}
                {applications.length > 3 && (
                  <div className="view-all-link">
                    <Link to="/vendor/applications">
                      View all {applications.length} applications →
                    </Link>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Quick Actions */}
          <div className="dashboard-section">
            <div className="section-header">
              <h2>Quick Actions</h2>
            </div>

            <div className="quick-actions">
              <Link to="/vendor/profile" className="action-card">
                <div className="action-icon">👤</div>
                <div className="action-content">
                  <h4>Manage Profile</h4>
                  <p>Update your business information</p>
                </div>
              </Link>

              <Link to="/vendor/applications" className="action-card">
                <div className="action-icon">📄</div>
                <div className="action-content">
                  <h4>Applications</h4>
                  <p>Manage your license applications</p>
                </div>
              </Link>

              <Link to="/vendors" className="action-card">
                <div className="action-icon">🔍</div>
                <div className="action-content">
                  <h4>Browse Vendors</h4>
                  <p>See other food trucks</p>
                </div>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const ApplicationCard = ({ application }) => {
  const getStatusColor = (status) => {
    const statusMap = {
      DRAFT: 'pending',
      SUBMITTED: 'submitted',
      UNDER_REVIEW: 'submitted',
      APPROVED: 'approved',
      REJECTED: 'rejected',
      INSPECTION_SCHEDULED: 'submitted',
      INSPECTION_COMPLETED: 'submitted',
      LICENSED: 'approved'
    };
    return statusMap[status] || 'pending';
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Not available';
    return new Date(dateString).toLocaleDateString();
  };

  return (
    <div className="application-card">
      <div className="app-header">
        <div className="app-id">Application #{application.id}</div>
        <span className={`status-badge ${getStatusColor(application.status)}`}>
          {application.status.replace('_', ' ')}
        </span>
      </div>
      <div className="app-details">
        <div className="app-detail">
          <strong>Created:</strong> {formatDate(application.createdAt)}
        </div>
        {application.submittedAt && (
          <div className="app-detail">
            <strong>Submitted:</strong> {formatDate(application.submittedAt)}
          </div>
        )}
      </div>
    </div>
  );
};

export default VendorDashboard;
